import{_ as r,c as a,o as p,af as o}from"./chunks/framework.BivmJ8bT.js";const g=JSON.parse('{"title":"npm","description":"","frontmatter":{},"headers":[],"relativePath":"program/npm/08-npm的“--force“和“--legacy-peer-deps“.md","filePath":"program/npm/08-npm的“--force“和“--legacy-peer-deps“.md","lastUpdated":1774860900000}'),t={name:"program/npm/08-npm的“--force“和“--legacy-peer-deps“.md"};function n(c,e,s,d,l,m){return p(),a("div",null,e[0]||(e[0]=[o('<h1 id="npm" tabindex="-1">npm <a class="header-anchor" href="#npm" aria-label="Permalink to &quot;npm&quot;">​</a></h1><h2 id="force" tabindex="-1">--force <a class="header-anchor" href="#force" aria-label="Permalink to &quot;--force&quot;">​</a></h2><p>f 或 --force：将强制 npm 获取远程资源，即使磁盘上存在本地副本也是如此。</p><h2 id="legacy-peer-deps" tabindex="-1">--legacy-peer-deps <a class="header-anchor" href="#legacy-peer-deps" aria-label="Permalink to &quot;--legacy-peer-deps&quot;">​</a></h2><p>NPM v7 预设会安裝 <code>peerDependencies</code>，这可能会导致有些模块出现依赖问题，这个时候可以在 <code>npm install</code> 的时候加上 <code>--legacy-peer-deps</code> 参数来解决。</p><blockquote><p>在很多情况下，这会导致版本冲突，从而中断安装过程。</p></blockquote><p><code>--legacy-peer-deps</code> 标志是在v7中引入的，目的是绕过 <code>peerDependency</code> 自动安装</p><p>它告诉 <strong>NPM</strong> 忽略项目中引入的各个 <strong>modules</strong> 之间的相同 <strong>modules</strong> 但不同版本的问题并继续安装，保证各个引入的依赖之间对自身所使用的不同版本 <strong>modules</strong> 共存。</p><hr><p><a href="https://blog.poychang.net/npm-install-with-legacy-peer-deps/" target="_blank" rel="noreferrer">安裝 NPM 套件時使用 --legacy-peer-deps 解決套件相依性問題</a></p>',10)]))}const i=r(t,[["render",n]]);export{g as __pageData,i as default};
